const triggerData = $('When Executed by Another Workflow').first().json;
const { whatsapp, person_identifier, horario_id, monto, comprobante_url } = triggerData;

if (!whatsapp) {
  throw new Error('Falta whatsapp en trigger');
}
if (!horario_id) {
  throw new Error('Falta horario_id');
}
if (!monto) {
  throw new Error('Falta monto');
}
if (!comprobante_url) {
  throw new Error('Falta comprobante_url (el comprobante debe estar ya subido a Drive antes de llamar esta tool)');
}

const wp = String(whatsapp).replace(/'/g, "''");
const pi = person_identifier ? String(person_identifier).replace(/'/g, "''") : null;
const hid = parseInt(horario_id);

let leadWhere;
if (pi) {
  // Si hay un solo lead con ese whatsapp, no exigir match exacto de person_identifier
  // (el agente puede mandar 'Nelson' cuando la BD guardo 'Nelson Rodriguez').
  // Si hay varios leads con el mismo whatsapp, exigir coincidencia parcial en cualquier direccion.
  leadWhere = `l.whatsapp = '${wp}' AND (
    (SELECT COUNT(*) FROM leads l2 WHERE l2.whatsapp = '${wp}') = 1
    OR l.person_identifier ILIKE '%' || '${pi}' || '%'
    OR '${pi}' ILIKE '%' || l.person_identifier || '%'
  )`;
} else {
  leadWhere = `l.whatsapp = '${wp}'`;
}

const query = `SELECT
  (SELECT to_jsonb(l) FROM leads l WHERE ${leadWhere} ORDER BY l.created_at DESC LIMIT 1) AS lead,
  (SELECT to_jsonb(h) FROM horarios h WHERE h.id = ${hid}) AS horario,
  (SELECT to_jsonb(a) FROM alumnos a WHERE a.whatsapp = '${wp}' ORDER BY a.created_at DESC LIMIT 1) AS alumno_existente;`;

return [{ json: { query } }];

const result = $input.first().json || {};
const lead = result.lead;
const horario = result.horario;
const alumnoExistente = result.alumno_existente;

if (!lead && !alumnoExistente) {
  throw new Error('No existe un lead ni un alumno con ese whatsapp.');
}
if (!horario) {
  throw new Error('No existe un horario con ese id.');
}

const cupoMax = (horario.cupo_maximo ?? horario.cupo_max);
const cupoActual = horario.cupo_actual ?? 0;
if (!alumnoExistente && cupoMax !== null && cupoMax !== undefined && cupoActual >= cupoMax) {
  throw new Error('Ese horario ya no tiene cupo disponible.');
}

const source = lead || alumnoExistente;

const esc = (v) => v === null || v === undefined ? null : String(v).replace(/'/g, "''");
const asSql = (v) => v === null ? 'null' : `'${v}'`;

const nombre = esc(source.nombre);
const apellido = esc(source.apellido);
const whatsapp = esc(source.whatsapp);
const email = esc(source.email);
const lead_tipo = esc(source.lead_tipo ?? source.categoria);
const categoria = esc(source.categoria ?? source.lead_tipo);
const origen = esc(source.origen);
const nivel = esc(source.nivel);
const objetivo = esc(source.objetivo);
const resumen = esc(source.resumen);
const disponibilidad = esc(source.disponibilidad);
const tags = esc(source.tags);
const notas = esc(source.notas);

const query = `INSERT INTO alumnos (nombre, apellido, whatsapp, email, lead_tipo, categoria, origen, nivel, objetivo, resumen, disponibilidad, tags, notas, estado, estado_motivo, estado_fecha, primer_contacto, ultimo_contacto, created_at, updated_at, activo)
VALUES (${asSql(nombre)}, ${asSql(apellido)}, ${asSql(whatsapp)}, ${asSql(email)}, ${asSql(lead_tipo)}, ${asSql(categoria)}, ${asSql(origen)}, ${asSql(nivel)}, ${asSql(objetivo)}, ${asSql(resumen)}, ${asSql(disponibilidad)}, ${asSql(tags)}, ${asSql(notas)}, 'REGISTRADO', 'Envió comprobante de pago y quedó registrado', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, true)
ON CONFLICT ON CONSTRAINT unique_whatsapp DO UPDATE SET
  estado = 'REGISTRADO',
  estado_motivo = CASE WHEN alumnos.estado = 'REGISTRADO' THEN alumnos.estado_motivo ELSE 'Envió comprobante de pago y quedó registrado' END,
  ultimo_contacto = CURRENT_TIMESTAMP,
  updated_at = CURRENT_TIMESTAMP
RETURNING id, nombre, whatsapp, estado;`;

return [{ json: { query, es_primer_pago: !alumnoExistente, horario_id: horario.id } }];

const alumno = $input.first().json;
const prev = $('Build Query Upsert Alumno').first().json;
const horarioId = prev.horario_id;

const query = `INSERT INTO alumnos_horarios (alumno_id, horario_id, fecha_inscripcion, activo)
VALUES (${alumno.id}, ${horarioId}, CURRENT_TIMESTAMP, true)
ON CONFLICT DO NOTHING;`;

return [{ json: { query, alumno_id: alumno.id, alumno_nombre: alumno.nombre, alumno_whatsapp: alumno.whatsapp, es_primer_pago: prev.es_primer_pago } }];

const prev = $('Build Query Vincular Horario').first().json;
const triggerData = $('When Executed by Another Workflow').first().json;
const {
  monto,
  tipo_pago,
  canal,
  moneda,
  periodo,
  comprobante_url,
  comprobante_monto,
  horario_id
} = triggerData;

const alumno_id = prev.alumno_id;
if (!alumno_id) {
  throw new Error('No se pudo obtener el id del alumno recién creado/actualizado.');
}

const TIPOS_VALIDOS = ['CUOTA_MENSUAL', 'PACK_4', 'PACK_8', 'INSCRIPCION', 'OTRO'];
const CANALES_VALIDOS = ['MERCADOPAGO', 'TRANSFERENCIA_BCO', 'EFECTIVO', 'OTRO'];

const montoNum = parseFloat(monto);
const compMontoNum = comprobante_monto ? parseFloat(comprobante_monto) : montoNum;

let tipo = tipo_pago ? String(tipo_pago).toUpperCase() : null;
if (!tipo || !TIPOS_VALIDOS.includes(tipo)) {
  tipo = prev.es_primer_pago ? 'INSCRIPCION' : 'CUOTA_MENSUAL';
}

let can = canal ? String(canal).toUpperCase() : null;
if (!can || !CANALES_VALIDOS.includes(can)) {
  can = 'OTRO';
}

const mon = moneda ? String(moneda).replace(/'/g, "''") : 'ARS';
const per = periodo ? String(periodo).replace(/'/g, "''") : new Date().toISOString().slice(0, 7);
const compUrl = String(comprobante_url).replace(/'/g, "''");
const horId = horario_id ? parseInt(horario_id) : null;

const query = `INSERT INTO pagos (alumno_id, horario_id, tipo, canal, monto, moneda, periodo, estado, comprobante_url, comprobante_fecha, comprobante_monto, created_at, updated_at)
VALUES (${alumno_id}, ${horId !== null ? horId : 'null'}, '${tipo}', '${can}', ${montoNum}, '${mon}', '${per}', 'PENDIENTE_VERIFICACION', '${compUrl}', CURRENT_DATE, ${compMontoNum}, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
RETURNING id, alumno_id, monto, estado, comprobante_url, periodo, created_at;`;

return [{ json: { query, alumno_id: prev.alumno_id, alumno_nombre: prev.alumno_nombre, alumno_whatsapp: prev.alumno_whatsapp } }];

const pago = $input.first().json;
const extra = $('Build Query Insert Pago').first().json;

return [{
  json: {
    success: true,
    message: 'Alumno registrado y comprobante recibido, pendiente de verificación por Fla',
    alumno: {
      id: extra.alumno_id,
      nombre: extra.alumno_nombre,
      whatsapp: extra.alumno_whatsapp,
      estado: 'REGISTRADO'
    },
    pago: {
      id: pago.id,
      alumno_id: pago.alumno_id,
      monto: pago.monto,
      estado: pago.estado,
      comprobante_url: pago.comprobante_url,
      periodo: pago.periodo,
      created_at: pago.created_at
    }
  }
}];
